package management

import "net/http"

func (s *Server) static(w http.ResponseWriter, r *http.Request) {
	switch r.URL.Path {
	case "/admin/":
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		w.Write([]byte(adminHTML))
	case "/admin/app.js":
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		w.Write([]byte(adminJS))
	case "/admin/style.css":
		w.Header().Set("Content-Type", "text/css; charset=utf-8")
		w.Write([]byte(adminCSS))
	default:
		http.NotFound(w, r)
	}
}

const adminHTML = `<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Code Marketplace</title><link rel="stylesheet" href="/admin/style.css"><script src="/admin/app.js" defer></script></head>
<body><header><a href="/admin/" class="brand">code-marketplace<span>/ kontrol</span></a><div class="account"><span id="identity"></span><button id="logout" hidden>Çıkış</button></div></header>
<main><p id="notice" role="status" aria-live="polite" hidden></p>
<section id="login"><h1>Giriş</h1><p class="muted">Active Directory hesabınızı kullanın.</p><form id="login-form"><label>Kullanıcı adı<input name="username" autocomplete="username" maxlength="256" required></label><label>Parola<input name="password" type="password" autocomplete="current-password" maxlength="4096" required></label><button type="submit" class="primary">Giriş yap</button></form></section>
<div id="dashboard" hidden><nav aria-label="Kontrol ekranları"><button id="tab-catalog" class="tab active" aria-pressed="true">Katalog <span id="count">0</span></button><button id="tab-imports" class="tab" aria-pressed="false">Import kayıtları</button><span class="readonly">Salt okunur</span><button id="refresh">Yenile</button></nav>
<section id="catalog-view"><div class="heading"><h1>Eklentiler</h1><input id="search" type="search" placeholder="Eklenti veya yayıncı ara" aria-label="Katalogda ara"></div><div class="table-wrap"><table><thead><tr><th>Eklenti</th><th>Yayıncı</th><th>Sürüm</th><th>Platform</th><th>Kabul kaydı</th></tr></thead><tbody id="catalog"></tbody></table></div><p id="empty" class="empty" hidden>Kayıt bulunamadı.</p>
<section class="policy"><h2>Kabul politikası</h2><dl><div><dt>Yayıncı</dt><dd id="mode"></dd></div><div><dt>İmza</dt><dd>Zorunlu</dd></div><div><dt>Sandbox</dt><dd id="sandbox-mode"></dd></div><div><dt>Rapor geçerliliği</dt><dd id="max-age"></dd></div></dl><div class="allowlist"><span>İzin listesi</span><p id="allowlist"></p></div></section></section>
<section id="imports-view" hidden><div class="heading"><h1>Import kayıtları</h1><span id="import-time" class="muted"></span></div><div class="table-wrap"><table><thead><tr><th>Dosya</th><th>Durum</th><th>Açıklama</th></tr></thead><tbody id="imports"></tbody></table></div><p id="imports-empty" class="empty" hidden>Henüz import kaydı yok.</p></section></div>
<footer><span>Code Marketplace</span><span>AGPL-3.0 · Coder temel alınarak geliştirilmiştir.</span></footer></main></body></html>`

const adminCSS = `:root{color-scheme:dark;font-family:"Cascadia Mono","SFMono-Regular",Consolas,"Liberation Mono",monospace;font-size:13px;line-height:1.5;color:#c8cacf;background:#17181a}*{box-sizing:border-box}body{margin:0}header{min-height:68px;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:0 32px;border-bottom:1px solid #303237}.brand{color:#ededee;text-decoration:none;font-size:14px;font-weight:600;white-space:nowrap}.brand span{font-weight:400;color:#92959d;margin-left:8px}.account{display:flex;align-items:center;gap:24px;font-size:12px}main{max-width:1240px;padding:32px;margin:auto}h1{font-size:22px;line-height:1.4;font-weight:500;letter-spacing:-.6px;margin:0}h2{font-size:13px;font-weight:500;color:#ededee;margin:0 0 24px}.muted{color:#9a9da5}.heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin:36px 0 24px}nav{display:flex;align-items:center;gap:24px;min-height:48px;border-bottom:1px solid #303237}.tab{border:0;padding:14px 0;position:relative;color:#9a9da5;border-radius:0;background:none}.tab.active{color:#ededee}.tab.active:after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:2px;background:#c8cacf}.tab span{margin-left:7px;color:#9a9da5;font-size:11px}.readonly{margin-left:auto;color:#9a9da5;font-size:11px}nav #refresh{font-size:11px;padding:5px 10px}button{font:inherit;font-size:12px;font-weight:400;background:transparent;color:#d1d3d7;border:1px solid #60636b;border-radius:2px;padding:9px 14px;cursor:pointer}button:hover{background:#24262a;color:#fff}button:disabled{opacity:.45;cursor:wait}#logout{border:0;padding:0;color:#9a9da5}#logout:hover{background:none;color:#fff}.primary{background:#d8d9dc;color:#17181a;border-color:#d8d9dc}.primary:hover{background:#f0f0f1;color:#17181a}input{display:block;width:100%;margin-top:8px;padding:10px 12px;border:1px solid #60636b;border-radius:2px;background:#1b1c1f;color:#ededee;font:inherit}input::placeholder{color:#92959d}input:focus,button:focus-visible{outline:1px solid #eee;outline-offset:3px}#search{width:280px;font-size:12px;margin:0;padding:9px 11px}label{display:block;margin:24px 0;color:#c8cacf;font-size:12px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left;font-size:12px;min-width:660px}th{color:#9a9da5;font-weight:400;font-size:11px;padding:12px 12px 12px 0;border-top:1px solid #303237;border-bottom:1px solid #303237;white-space:nowrap}td{padding:18px 12px 18px 0;border-bottom:1px solid #2b2d32;vertical-align:top;max-width:380px;overflow-wrap:anywhere}td:first-child{color:#e1e2e5}td span{display:block;color:#9a9da5;font-size:11px;margin-top:5px}.version,.platform{white-space:nowrap}.status{font-size:11px;color:#c8cacf;white-space:nowrap}.empty{padding:32px 0;color:#9a9da5}.policy{border-top:1px solid #303237;margin-top:48px;padding-top:24px}.policy dl{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin:0}.policy dt{font-size:11px;color:#9a9da5;margin-bottom:8px}.policy dd{margin:0;color:#dedfe2;font-size:12px}.allowlist{display:flex;gap:24px;align-items:baseline;border-top:1px solid #2b2d32;margin-top:24px;padding-top:16px;font-size:12px}.allowlist span{font-size:11px;color:#9a9da5;white-space:nowrap}.allowlist p{margin:0;overflow-wrap:anywhere}#login{max-width:360px;margin:9vh auto 14vh}#login>p{font-size:12px;margin:12px 0 32px}#login-form .primary{width:100%;margin-top:8px}#notice{border-left:2px solid #9a9da5;background:#202226;padding:12px 16px;margin:0 0 24px;font-size:12px}#notice.error{border-left-color:#dedfe2;color:#ededee}footer{display:flex;justify-content:space-between;gap:24px;border-top:1px solid #303237;margin-top:56px;padding-top:18px;font-size:10px;color:#9a9da5}[hidden]{display:none!important}@media(max-width:720px){header{padding:0 18px;gap:12px}.brand span{display:none}.account{gap:16px}#identity{max-width:120px;overflow:hidden;text-overflow:ellipsis}main{padding:24px 18px}nav{gap:18px;flex-wrap:wrap}.readonly{display:none}nav #refresh{margin-left:auto}.heading{align-items:flex-start;flex-direction:column;gap:18px;margin:28px 0 20px}#search{width:100%}.policy dl{grid-template-columns:repeat(2,1fr)}footer{flex-direction:column;gap:8px}.allowlist{flex-direction:column;gap:8px}#login{margin:7vh auto 12vh}}`

const adminJS = `"use strict";
const el=id=>document.getElementById(id);
let session=null,entries=[];
const notice=(message,error=false)=>{el("notice").textContent=message;el("notice").className=error?"error":"";el("notice").hidden=false};
async function request(path,options={}){const headers={...options.headers};if(options.body){headers["Content-Type"]="application/json";if(session)headers["X-CSRF-Token"]=session.csrfToken}const response=await fetch("/admin/api/"+path,{...options,headers,credentials:"same-origin",cache:"no-store"});if(response.status===204)return null;const data=await response.json();if(!response.ok){if(response.status===401){session=null;showLogin()}throw new Error(data.error||"İşlem başarısız")}return data}
function showLogin(){el("login").hidden=false;el("dashboard").hidden=true;el("logout").hidden=true;el("identity").textContent=""}
function showDashboard(){el("login").hidden=true;el("dashboard").hidden=false;el("logout").hidden=false;el("identity").textContent=session.user.name}
function selectView(name){for(const view of ["catalog","imports"]){const active=view===name;el(view+"-view").hidden=!active;el("tab-"+view).classList.toggle("active",active);el("tab-"+view).setAttribute("aria-pressed",String(active))}}
function cell(row,text,className=""){const td=document.createElement("td");td.textContent=text;td.className=className;row.append(td);return td}
function renderCatalog(){const tbody=el("catalog");tbody.replaceChildren();const search=el("search").value.toLocaleLowerCase();for(const entry of entries){if(!(entry.publisher+"."+entry.extension+" "+entry.displayName).toLocaleLowerCase().includes(search))continue;const row=document.createElement("tr"),identity=cell(row,entry.displayName||entry.extension);if(entry.displayName&&entry.displayName!==entry.extension){const name=document.createElement("span");name.textContent=entry.extension;identity.append(name)}cell(row,entry.publisher);cell(row,entry.version.version,"version");cell(row,entry.version.targetPlatform||"universal","platform");cell(row,entry.receipt?(entry.receipt.sandboxMode==="disabled"?"Sandbox kapalı":entry.receipt.sandbox?.verdict==="clean"?"Sandbox onaylı":"Tarama kaydı yok")+(entry.receipt.publisher?.publisher?.isDomainVerified?" · Verified":""):"Kabul belgesi yok");tbody.append(row)}el("count").textContent=entries.length;el("empty").hidden=tbody.children.length>0}
function duration(value){let seconds=0;for(const match of value.matchAll(/([\d.]+)(h|m|s)/g))seconds+=Number(match[1])*({h:3600,m:60,s:1}[match[2]]);for(const [size,label] of [[86400,"gün"],[3600,"saat"],[60,"dakika"]])if(seconds>0&&seconds%size===0)return seconds/size+" "+label;return value}
async function refresh(){const [catalog,policy,imports]=await Promise.all([request("catalog"),request("policy"),request("imports")]);entries=catalog.entries;renderCatalog();el("sandbox-mode").textContent=policy.sandboxRequired?"Zorunlu":"Kapalı";el("mode").textContent={verified:"Verified",allowlist:"İzin listesi",any:"Tümü"}[policy.mode]||policy.mode;el("max-age").textContent=duration(policy.maxAge);el("allowlist").textContent=policy.allowedPublishers.length?policy.allowedPublishers.join(", "):policy.mode==="verified"?"Tüm verified yayıncılar":policy.mode==="any"?"Sınırlama yok":"İzin verilen yayıncı yok";el("import-time").textContent=imports.completedAt?new Date(imports.completedAt).toLocaleString("tr-TR"):"";el("imports").replaceChildren();const statuses={imported:"İçe alındı",unchanged:"Mevcut",waiting:"Bekliyor",rejected:"Reddedildi",conflict:"Çakışma",failed:"Hata"};for(const result of imports.results){const row=document.createElement("tr");cell(row,result.file);cell(row,statuses[result.status]||result.status,"status");cell(row,[result.reason,result.archiveError,result.archiveStatus==="archived"?"Arşiv: "+result.archivedTo:"",result.recoveryDir?"Kurtarma: "+result.recoveryDir:"",result.missingDependencies?.length?"Eksik bağımlılık: "+result.missingDependencies.join(", "):""].filter(Boolean).join(" · "));el("imports").append(row)}el("imports-empty").hidden=imports.results.length>0}
el("login-form").addEventListener("submit",async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector("button");button.disabled=true;try{session=await request("login",{method:"POST",body:JSON.stringify({username:form.elements.username.value,password:form.elements.password.value})});form.elements.password.value="";el("notice").hidden=true;showDashboard();await refresh()}catch(error){form.elements.password.value="";notice(error.message,true)}finally{button.disabled=false}});
el("logout").addEventListener("click",async()=>{try{await request("logout",{method:"POST",body:"{}"});session=null;showLogin()}catch(error){notice(error.message,true)}});
el("refresh").addEventListener("click",async()=>{const button=el("refresh");button.disabled=true;try{await refresh()}catch(error){notice(error.message,true)}finally{button.disabled=false}});
el("search").addEventListener("input",renderCatalog);
el("tab-catalog").addEventListener("click",()=>selectView("catalog"));
el("tab-imports").addEventListener("click",()=>selectView("imports"));
request("session").then(async data=>{session=data;showDashboard();await refresh()}).catch(()=>showLogin());`
